run_surface "s7"  "bencrane/hq-all" "fl" 'false # AUDIT: fill — entities.source_state_contractor_fl table-exists + column-checksum + raw_source_row jsonb column (DBPR/CILB)'
# Surface s8 — FL code
run_surface "s8"  "bencrane/hq-all" "fl" 'false # AUDIT: fill — scripts/run_state_contractor_fl_ingest.py exists + parses + ON CONFLICT (<fl-PK>) + raw_source_row populated + 2-run idempotency'
# Surface s9 — FL deploy + schedule
run_surface "s9"  "bencrane/hq-all" "fl" 'false # AUDIT: fill — railway status data-engine-x latestDeployment SUCCESS at $MERGE_SHA + per-state schedule registration target'
# Surface s10 — AZ migration
run_surface "s10" "bencrane/hq-all" "az" 'false # AUDIT: fill — entities.source_state_contractor_az table-exists + column-checksum + raw_source_row jsonb column (ROC)'
# Surface s11 — AZ code
run_surface "s11" "bencrane/hq-all" "az" 'false # AUDIT: fill — scripts/run_state_contractor_az_ingest.py exists + parses + ON CONFLICT (<az-PK>) + raw_source_row populated + 2-run idempotency'
# Surface s12 — AZ deploy + schedule
run_surface "s12" "bencrane/hq-all" "az" 'false # AUDIT: fill — railway status data-engine-x latestDeployment SUCCESS at $MERGE_SHA + per-state schedule registration target'
# Surface s13 — NC migration
run_surface "s13" "bencrane/hq-all" "nc" 'false # AUDIT: fill — entities.source_state_contractor_nc table-exists + column-checksum + raw_source_row jsonb column (NCLBGC)'
# Surface s14 — NC code
run_surface "s14" "bencrane/hq-all" "nc" 'false # AUDIT: fill — scripts/run_state_contractor_nc_ingest.py exists + parses + ON CONFLICT (<nc-PK>) + raw_source_row populated + 2-run idempotency'
# Surface s15 — NC deploy + schedule
run_surface "s15" "bencrane/hq-all" "nc" 'false # AUDIT: fill — railway status data-engine-x latestDeployment SUCCESS at $MERGE_SHA + per-state schedule registration target'

